export function createJourney({ repo, bus, clock = systemClock }: JourneyDeps) {
  async function createTask(input: CreateTaskInput): Promise<Task> {
    const now = clock.now();
    const task: Task = {
      id: newId(now),
      personId: input.personId,
      kind: input.kind,
      title: input.title,
      dueDate: input.dueDate ?? businessDate(now),
      createdAt: now.toISOString(),
    };
    await repo.insert(task);
    return task;
  }

  /**
   * The advisor calls each new person. The task is due on the business date of the
   * registration, not of the handling, because the queue may deliver the event later.
   * The queue delivers at least once, so a repeated event creates no second task.
   */
  bus.subscribe<PersonRegistered>("identity.person-registered", async (event) => {
    const { personId } = event.payload;
    const tasks = await repo.listByPerson(personId);
    if (tasks.some((t) => t.kind === WELCOME_CALL_KIND)) return;
    await createTask({
      personId,
      kind: WELCOME_CALL_KIND,
      title: "Welcome call",
      dueDate: businessDate(new Date(event.occurredAt)),
    });
  });

  return {
    createTask,

    async listTasks(personId: string): Promise<Task[]> {
      return repo.listByPerson(personId);
    },
  };
}

