describe("journey", () => {
  it("creates a task due today by default", async () => {
    const journey = createJourney({
      repo: new InMemoryTaskRepository(),
      bus: new InMemoryEventBus(),
      clock: fixedClock("2027-01-05T08:00:00Z"),
